#if UNITY_EDITOR
using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;
namespace DeliveryService.Mok.Editor{public static class AftermathToolPlacement{public static void Apply(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/PrisonAftermath.unity");EditorSceneManager.SaveScene(scene,"Logs/Aftermath-before-toolplacement.unity",true);var f=Object.FindFirstObjectByType<AftermathFilm>();var root=f.shots[1].set.transform.Find("민기의 생활과 작업 흔적");var table=root.GetComponentsInChildren<Transform>().First(t=>t.name=="SM_Prop_Table_01");Bounds Bounds(Transform t){var rs=t.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}float top=Bounds(table).max.y;
foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("SM_Item_")&&(t.name.Contains("Wrench")||t.name.Contains("ScrewDriver")||t.name.Contains("Hammer")))){var b=Bounds(t);var target=new Vector3(b.center.x,top+.003f,b.center.z);if(b.size.x<b.size.y&&b.size.x<b.size.z)t.rotation=Quaternion.AngleAxis(90,Vector3.forward)*t.rotation;else if(b.size.z<b.size.y)t.rotation=Quaternion.AngleAxis(90,Vector3.right)*t.rotation;b=Bounds(t);t.position+=target-new Vector3(b.center.x,b.min.y,b.center.z);}
EditorSceneManager.SaveScene(scene);AftermathReview.Record();}}}
#endif
